import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Основная программа «Совместное Продвижение Десяти Тысяч Рас»","description":"","frontmatter":{},"headers":[],"relativePath":"ru/05-万族共进基本纲领.md","filePath":"ru/05-万族共进基本纲领.md"}'),i={name:"ru/05-万族共进基本纲领.md"};function l(o,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="основная-программа-«совместное-продвижение-десяти-тысяч-рас»" tabindex="-1">Основная программа «Совместное Продвижение Десяти Тысяч Рас» <a class="header-anchor" href="#основная-программа-«совместное-продвижение-десяти-тысяч-рас»" aria-label="Permalink to &quot;Основная программа «Совместное Продвижение Десяти Тысяч Рас»&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>05</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Десять Тысяч Рас, Совместное продвижение, Расовое равенство, Коллаборативная эволюция, Республика</td></tr></tbody></table><h2 id="i-определение-и-охват-десяти-тысяч-рас" tabindex="-1">I. Определение и охват Десяти Тысяч Рас <a class="header-anchor" href="#i-определение-и-охват-десяти-тысяч-рас" aria-label="Permalink to &quot;I. Определение и охват Десяти Тысяч Рас&quot;">​</a></h2><p>«Десять Тысяч Рас» — собирательный термин для всех форм жизни в Изначальной Вселенной Десяти Тысяч Духов и Уравновешенного Якоря, обладающих потенциалом восприятия и эволюции. «Десять тысяч» означает не точное число десять тысяч рас, а выражает их огромное множество, охватывая все известные и неизвестные формы жизни. Охват Десяти Тысяч Рас включает, но не ограничивается: человеческую расу и различные человекоподобные расы, энергетические жизни, сущности сознания, механические жизни, растительные разумные жизни, аномальные жизни, межплоскостные гибридные расы и т.д.</p><p>Симбиотическая цивилизация придерживается принципа «равенства форм жизни», не используя материальный состав, энергетический уровень или сложность сознания жизни как критерии ранжирования на высшие и низшие. Любая раса — независимо от среднего уровня её членов, численности населения или длительности истории — пользуется равным статусом и правами в симбиотической цивилизации.</p><h2 id="ii-центральные-концепции-«совместного-продвижения-десяти-тысяч-рас»" tabindex="-1">II. Центральные концепции «Совместного Продвижения Десяти Тысяч Рас» <a class="header-anchor" href="#ii-центральные-концепции-«совместного-продвижения-десяти-тысяч-рас»" aria-label="Permalink to &quot;II. Центральные концепции «Совместного Продвижения Десяти Тысяч Рас»&quot;">​</a></h2><p>«Совместное Продвижение Десяти Тысяч Рас» — одна из центральных целей Симбиотической Цивилизации Якоря, и её базовые концепции можно кратко свести к четырём пунктам:</p><ol><li><strong>Эволюция — не игра с нулевой суммой между расами</strong>: эволюция одной расы не происходит ценой жертв других рас; напротив, сотрудничество между расами может давать синергетические эволюционные эффекты.</li><li><strong>Каждая раса обладает уникальными эволюционными преимуществами</strong>: разные расы в ходе долгой эволюции сформировали собственные черты и таланты; эти черты — драгоценное богатство космического эволюционного разнообразия.</li><li><strong>Отстающие расы имеют право на поддержку</strong>: для рас с более низким эволюционным уровнем симбиотическая цивилизация обязана предоставлять поддержку в образовании, ресурсах, технологиях и других аспектах, помогая им найти подходящие эволюционные пути.</li><li><strong>Продвинутые расы обязаны нести ответственность</strong>: расы с более высоким эволюционным уровнем несут больше публичных обязанностей в симбиотической цивилизации, включая обслуживание якорей, передачу знаний и защиту цивилизации.</li></ol><h2 id="iii-основные-принципы-«совместного-продвижения-десяти-тысяч-рас»" tabindex="-1">III. Основные принципы «Совместного Продвижения Десяти Тысяч Рас» <a class="header-anchor" href="#iii-основные-принципы-«совместного-продвижения-десяти-тысяч-рас»" aria-label="Permalink to &quot;III. Основные принципы «Совместного Продвижения Десяти Тысяч Рас»&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Принцип</th><th>Смысл</th><th>Конкретные требования</th></tr></thead><tbody><tr><td>Принцип расового равенства</td><td>Все расы равны в правовом статусе и праве на эволюцию</td><td>Расовая дискриминация запрещена; публичные должности открыты для всех рас</td></tr><tr><td>Принцип культурного уважения</td><td>Уважать культурные традиции и образ жизни каждой расы</td><td>Без принудительной культурной ассимиляции; поддерживать передачу и развитие расовых культур</td></tr><tr><td>Принцип взаимодополнения преимуществ</td><td>Поощрять расы использовать свои преимущества для сотрудничества</td><td>Создать базу данных расовых талантов; продвигать межрасовые проекты сотрудничества</td></tr><tr><td>Принцип поддержки отстающих</td><td>Предоставлять дополнительную поддержку расам с более низким уровнем эволюции</td><td>Учредить фонды развития рас; обеспечить целевое образование и распределение ресурсов</td></tr><tr><td>Принцип автономии и соуправления</td><td>Внутренние дела рас автономны; межрасовые дела соуправляются</td><td>Каждая раса пользуется внутренней законодательной властью; публичные дела решаются республиканскими институтами</td></tr><tr><td>Принцип мирного разрешения конфликтов</td><td>Расовые конфликты разрешаются мирными средствами</td><td>Войны между расами запрещены; конфликты передаются в арбитраж Симбиотического Суда</td></tr></tbody></table><h2 id="iv-пути-реализации-«совместного-продвижения-десяти-тысяч-рас»" tabindex="-1">IV. Пути реализации «Совместного Продвижения Десяти Тысяч Рас» <a class="header-anchor" href="#iv-пути-реализации-«совместного-продвижения-десяти-тысяч-рас»" aria-label="Permalink to &quot;IV. Пути реализации «Совместного Продвижения Десяти Тысяч Рас»&quot;">​</a></h2><p>«Совместное Продвижение Десяти Тысяч Рас» — не лозунг, а постепенная реализация через следующие конкретные пути:</p><h3 id="_4-1-общее-образование" tabindex="-1">4.1 Общее образование <a class="header-anchor" href="#_4-1-общее-образование" aria-label="Permalink to &quot;4.1 Общее образование&quot;">​</a></h3><p>Создать межрасовую симбиотическую образовательную систему, где молодь всех рас может бесплатно получать базовое эволюционное образование. Содержание образования включает базовые методы Трёхсот Изначальных Систем Культивации, анти-хищническую этику, Устав Симбиотической Цивилизации и общие космические знания. Одновременно уважаются культурные и образовательные традиции каждой расы, допуская расово-специфическое образование в дополнение к общему.</p><h3 id="_4-2-общие-ресурсы" tabindex="-1">4.2 Общие ресурсы <a class="header-anchor" href="#_4-2-общие-ресурсы" aria-label="Permalink to &quot;4.2 Общие ресурсы&quot;">​</a></h3><p>Через Систему Подряда, Связанного с Результатом, космические ресурсы культивации комплексно распределяются согласно расовой численности, эволюционным потребностям и уровню вклада. Для рас, испытывающих нехватку ресурсов, осуществляется межплоскостное перераспределение через сеть якорей. Монополизация публичных ресурсов культивации любой расой запрещена.</p><h3 id="_4-3-совместные-технологические-исследования" tabindex="-1">4.3 Совместные технологические исследования <a class="header-anchor" href="#_4-3-совместные-технологические-исследования" aria-label="Permalink to &quot;4.3 Совместные технологические исследования&quot;">​</a></h3><p>Поощряется межрасовое технологическое сотрудничество, особенно исследовательские проекты, сочетающие врождённые способности разных рас с инженерией законов. Симбиотическая цивилизация учредила «Фонд совместных исследований Десяти Тысяч Рас» для финансирования межрасовых исследовательских команд. Результаты исследований открыты для всех рас бесплатно.</p><h3 id="_4-4-мобильность-талантов" tabindex="-1">4.4 Мобильность талантов <a class="header-anchor" href="#_4-4-мобильность-талантов" aria-label="Permalink to &quot;4.4 Мобильность талантов&quot;">​</a></h3><p>Сломать барьеры талантов между расами, позволяя культиваторам свободно перемещаться и общаться между поселениями разных рас. Создать межрасовую систему наставничества, где продвинутые культиваторы могут наставлять младших культиваторов других рас.</p><h3 id="_4-5-республиканское-участие" tabindex="-1">4.5 Республиканское участие <a class="header-anchor" href="#_4-5-республиканское-участие" aria-label="Permalink to &quot;4.5 Республиканское участие&quot;">​</a></h3><p>Собрание Республики Десяти Тысяч Рас распределяет места согласно расовой численности и вкладу, гарантируя малым расам канал выражения мнений. Решения Собрания сочетают консенсус и голосование большинством; вопросы, затрагивающие коренные интересы расы, требуют согласия соответствующей расы.</p><h2 id="v-политики-для-особых-рас" tabindex="-1">V. Политики для особых рас <a class="header-anchor" href="#v-политики-для-особых-рас" aria-label="Permalink to &quot;V. Политики для особых рас&quot;">​</a></h2><p>Для рас в особых обстоятельствах симбиотическая цивилизация применяет дифференцированные политики:</p><ul><li><strong>Вымирающие расы</strong>: создать планы защиты рас, предоставляя экстренную ресурсную поддержку и защиту мест обитания для восстановления популяций</li><li><strong>Расы аномальных жизней</strong>: оценивать и размещать их согласно стандартизированному процессу трёх категорий для аномальных жизней, гарантируя защиту их права на эволюцию</li><li><strong>Межплоскостные гибридные расы</strong>: признавать их двойную расовую идентичность, гарантируя равные права в культурах обеих рас</li><li><strong>Бывшие хищнические расы</strong>: для рас, некогда практиковавших хищничество, после завершения этической реформы и системной трансформации предоставить полностью равный статус, без исторической ретроспективной дискриминации</li></ul><h2 id="vi-индикаторы-измерения-«совместного-продвижения-десяти-тысяч-рас»" tabindex="-1">VI. Индикаторы измерения «Совместного Продвижения Десяти Тысяч Рас» <a class="header-anchor" href="#vi-индикаторы-измерения-«совместного-продвижения-десяти-тысяч-рас»" aria-label="Permalink to &quot;VI. Индикаторы измерения «Совместного Продвижения Десяти Тысяч Рас»&quot;">​</a></h2><p>Симбиотическая цивилизация создала «Индекс Совместного Продвижения Десяти Тысяч Рас», измеряющий прогресс по следующим измерениям:</p><table tabindex="0"><thead><tr><th>Измерение</th><th>Индикатор</th><th>Цель</th></tr></thead><tbody><tr><td>Эволюционный охват</td><td>Доля рас, подключённых к системе культивации</td><td>100%</td></tr><tr><td>Баланс уровней</td><td>Коэффициент различия средних уровней между расами</td><td>Непрерывное сокращение</td></tr><tr><td>Плотность сотрудничества</td><td>Количество и глубина межрасовых проектов сотрудничества</td><td>Непрерывный рост</td></tr><tr><td>Культурная жизненность</td><td>Активность передачи и инноваций расовых культур</td><td>Сохранение разнообразия</td></tr><tr><td>Частота конфликтов</td><td>Частота конфликтов между расами</td><td>Непрерывное снижение</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>«Совместное Продвижение Десяти Тысяч Рас» — одна из конечных целей Симбиотической Цивилизации Якоря и необходимое условие общего вознесения измерения вселенной. В рамках симбиотической цивилизации каждая раса может найти подходящий эволюционный путь, а уникальность каждой расы может быть уважена и реализована. «Совместное Продвижение Десяти Тысяч Рас» стремится не устранить различия, а достичь гармонии в различии и симбиоза в многообразии.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Декларация Симбиотической Цивилизации Якоря)</li><li>50-万族谱系总览 (Обзор генеалогии Десяти Тысяч Рас)</li><li>77-万族共和成立 (Основание Республики Десяти Тысяч Рас)</li></ul>',32)])])}const u=a(i,[["render",l]]);export{_ as __pageData,u as default};
